import{_ as n,C as a,o as r,c as i,j as e,a as o,E as d,ao as c}from"./chunks/framework.D7TN4pt9.js";const k=JSON.parse('{"title":"Running several agents","description":"","frontmatter":{},"headers":[],"relativePath":"guide/agents.md","filePath":"guide/agents.md","lastUpdated":null}'),l={name:"guide/agents.md"};function h(p,t,g,w,u,m){const s=a("DemoLoop");return r(),i("div",null,[t[0]||(t[0]=e("h1",{id:"Running-several-agents",tabindex:"-1"},[o("Running several agents "),e("a",{class:"header-anchor",href:"#Running-several-agents","aria-label":'Permalink to "Running several agents {#Running-several-agents}"'},"​")],-1)),t[1]||(t[1]=e("p",null,[o("Ship of Tools is built for more than one agent at a time. Every session is a "),e("strong",null,"row"),o(" in Sessions mode: a project directory with its own Julia REPL and an agent pane running "),e("strong",null,"Claude Code"),o(", "),e("strong",null,"Codex"),o(", or a bare shell (see "),e("a",{href:"/ship-of-tools/stable/concepts/sessions#session-model"},"Hosts, sessions, REPLs"),o("). You move between rows from the keyboard, and each row's color tells you whether it needs you.")],-1)),d(s,{name:"sessions",caption:"Demo session rows changing color as a script sets their work states: green working, red waiting for your answer, purple waiting on a job, blue done, gray idle."}),t[2]||(t[2]=c('<h2 id="Start-a-session" tabindex="-1">Start a session <a class="header-anchor" href="#Start-a-session" aria-label="Permalink to &quot;Start a session {#Start-a-session}&quot;">​</a></h2><p>Press <strong><code>s</code></strong> for Sessions mode and pick <strong><code>[+ create new]</code></strong>; the steps are in <a href="/ship-of-tools/stable/start/quickstart#start-session">Start an agent session</a>.</p><p>The daemon starts the agent in its own supervised <strong>capsule</strong>, so it keeps running when you switch rows or lose the connection, and when you close a window on a computer that does not run the backend. Closing the last window on the computer that runs the backend ends its sessions unless you answer Yes to the <code>Ctrl+Q</code> prompt; see <a href="./../start/running">What keeps running</a>.</p><h2 id="Move-between-sessions" tabindex="-1">Move between sessions <a class="header-anchor" href="#Move-between-sessions" aria-label="Permalink to &quot;Move between sessions {#Move-between-sessions}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">Key</th><th style="text-align:right;">Action</th></tr></thead><tbody><tr><td style="text-align:right;"><code>s</code></td><td style="text-align:right;">Sessions mode — every row on every connected host, grouped by host</td></tr><tr><td style="text-align:right;"><code>Shift+ArrowRight</code> / <code>Shift+ArrowLeft</code></td><td style="text-align:right;">cycle the active session from anywhere</td></tr><tr><td style="text-align:right;"><code>Primary+Arrow</code></td><td style="text-align:right;">move focus between panes inside the session</td></tr></tbody></table><p>Switching rows is a frontend state change: it never restarts a session&#39;s REPL, so the REPL holding <code>x = 5</code> still holds it when you come back.</p><h2 id="Read-the-colors" tabindex="-1">Read the colors <a class="header-anchor" href="#Read-the-colors" aria-label="Permalink to &quot;Read the colors {#Read-the-colors}&quot;">​</a></h2><p>Each row is colored by the agent&#39;s work state, so you can scan the list instead of tabbing through each pane; the colors are in <a href="./../concepts/work-state">Work-state colors</a>. All keys are in the <a href="./../ref/keybindings">keybindings reference</a>.</p><h2 id="One-worktree-per-agent" tabindex="-1">One worktree per agent <a class="header-anchor" href="#One-worktree-per-agent" aria-label="Permalink to &quot;One worktree per agent {#One-worktree-per-agent}&quot;">​</a></h2><p>Parallel agents on one repository should not share a checkout. The bundled <code>worktree</code> skill (<code>/worktree</code> in a Claude Code session, backed by <code>comm-worktree-new.sh &lt;short&gt;</code>) creates a git worktree next to the repo and spawns a new session bound to it:</p><ul><li><p>directory <code>&lt;repo-parent&gt;/worktrees/&lt;repo&gt;-wt-&lt;short&gt;</code> (never inside the repo),</p></li><li><p>branch <code>wt/&lt;short&gt;</code> off the current <code>HEAD</code>,</p></li><li><p>a session labeled <code>&lt;repo&gt;-wt-&lt;short&gt;</code> (a committed <code>.sot/worktree.toml</code> <code>display_prefix</code>, or <code>--display-prefix</code>, replaces the repo name in the label), listed next to the parent row.</p></li></ul><p><code>/worktree status</code> shows the family and whether each worktree is ready to clean up, <code>/worktree sync</code> reminds the parent and worktree sessions to sync, and <code>/worktree clean</code> tears a finished one down. The same scripts (<code>comm-worktree-new.sh</code>, <code>-status.sh</code>, <code>-sync.sh</code>, <code>-clean.sh</code>) live in <code>~/.sot-comm/bin</code> for use from any shell.</p><h2 id="Hand-work-to-a-new-agent-in-another-repo" tabindex="-1">Hand work to a new agent in another repo <a class="header-anchor" href="#Hand-work-to-a-new-agent-in-another-repo" aria-label="Permalink to &quot;Hand work to a new agent in another repo {#Hand-work-to-a-new-agent-in-another-repo}&quot;">​</a></h2><p><code>comm-spawn.sh &lt;repo-path&gt; --task &quot;...&quot;</code> starts a new agent session on another package and has it report back to you over the comm relay. Combined with <a href="./messaging">agent messaging</a>, one session can fan work out to several others and collect their answers.</p><p><code>comm-spawn.sh &lt;repo-path&gt; --agent none</code> starts a shell row instead, with no agent: it prints the row&#39;s workspace id and the <code>comm-despawn.sh</code> command that ends it. A row made this way appears in the session strip without moving the window off the row you are on.</p><h2 id="A-separate-subscription-per-session" tabindex="-1">A separate subscription per session <a class="header-anchor" href="#A-separate-subscription-per-session" aria-label="Permalink to &quot;A separate subscription per session {#A-separate-subscription-per-session}&quot;">​</a></h2><p>A session runs under the agent&#39;s default login unless you pick another account folder in the session picker; rows running under one show a <code>· &lt;name&gt;</code> suffix. How to add an account is in <a href="/ship-of-tools/stable/guide/modes#Accounts">Modes</a>.</p>',17))])}const f=n(l,[["render",h]]);export{k as __pageData,f as default};
